import bisect, hashlib

def token(s: str) -> int:
    # Stable across processes and languages. Never use hash().
    return int(hashlib.md5(s.encode()).hexdigest(), 16)

class ConsistentHash:
    def __init__(self, nodes, vnodes=200):
        self.vnodes = vnodes
        self.ring: list[tuple[int, str]] = []
        for n in nodes:
            self.add_node(n)

    def add_node(self, node: str):
        for i in range(self.vnodes):
            self.ring.append((token(f"{node}#{i}"), node))
        self.ring.sort()  # O(V log V) on membership change, not per request

    def remove_node(self, node: str):
        self.ring = [(t, n) for t, n in self.ring if n != node]

    def owner(self, key: str) -> str:
        h = token(key)
        keys = [t for t, _ in self.ring]
        idx = bisect.bisect_right(keys, h) % len(self.ring)
        return self.ring[idx][1]

# Naive modulo for contrast: fast but remaps ~all keys on N change.
def naive_owner(key: str, nodes: list[str]) -> str:
    return nodes[token(key) % len(nodes)]
